<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import PageHeading from '../components/PageHeading.vue'
import StatePanel from '../components/StatePanel.vue'
import ScientificPlot from '../components/ScientificPlot.vue'
import {api,ApiError,errorText} from '../api'
import {stages} from '../measurements/model'
import {useAuth} from '../auth'
const route=useRoute(),auth=useAuth()
const sampleId=ref(''),stage=ref(''),processId=ref(''),batchId=ref(''),samples=ref<any[]>([]),batches=ref<any[]>([]),processes=ref<any[]>([]),measurements=ref<any[]>([]),selected=ref<number[]>([]),result=ref<any>(null),error=ref(''),busy=ref(false),includeOutliers=ref(true),reason=ref(''),excluded=ref<string[]>([]),before=ref(''),after=ref(''),confirmPair=ref(false),saveLabel=ref(''),saved=ref(''),jobId=ref(''),previewItems=ref<any[]>([]),previewRefs=ref<string[]>([]),models=ref<any[]>([])
const sourceMode=ref('measurement'),previewDeclarations=ref<Record<string,{sample_id:string;stage:string;stage_seq:string;optical_model_id:string;confirmed:boolean}>>({}),stale=ref(false)
const savedRecord=ref<any>(null),pairWarning=ref('')
let revision=0
const selectedRows=computed(()=>measurements.value.filter(m=>selected.value.includes(m.measurement_id)))
const previewOptions=computed(()=>previewItems.value.flatMap(i=>(i.parse_result?.status==='parsed'?i.parse_result.blocks:[]).map((_:any,n:number)=>({key:`${i.item_id}:${n}`,item:i,index:n,label:`${i.filename} · 块 ${n+1}`}))))
const pairOptions=computed(()=>sourceMode.value==='measurement'?selectedRows.value.map((m:any)=>({label:m.measurement_code,key:String(m.measurement_id)})):previewOptions.value.filter((p:any)=>previewRefs.value.includes(p.key)).map((p:any)=>({key:p.key,label:p.label})))
function clearResult(){pairWarning.value='';stale.value=false;revision++;busy.value=false;result.value=null;saved.value='';savedRecord.value=null;excluded.value=[];before.value='';after.value='';confirmPair.value=false}
async function searchSamples(keyword=''){try{samples.value=(await api<any[]>('/imports/options/samples',{query:{keyword,size:100}})).data}catch(e){error.value=errorText(e)}}
async function loadMeasurements(){clearResult();selected.value=[];error.value='';if(sourceMode.value!=='measurement')return;try{measurements.value=(await api<any[]>('/analysis/measurements',{query:{sample_id:sampleId.value,batch_id:batchId.value,stage:stage.value,process_id:processId.value}})).data}catch(e){error.value=errorText(e)}}
async function searchProcesses(keyword=''){try{processes.value=(await api<any[]>('/processes',{query:{keyword,size:100}})).data}catch(e){error.value=errorText(e)}}
async function processChanged(){sampleId.value='';stage.value='';batchId.value='';if(processId.value){try{samples.value=(await api<any[]>(`/processes/${processId.value}/samples`)).data.map((r:any)=>r.sample)}catch(e){error.value=errorText(e)}}else await searchSamples();await loadMeasurements()}
async function sampleChanged(){await loadMeasurements()}
async function batchChanged(){sampleId.value='';processId.value='';measurements.value=[];selected.value=[];clearResult();try{samples.value=(await api<any[]>('/samples',{query:{batch_id:batchId.value,size:200}})).data;await loadMeasurements()}catch(e){error.value=errorText(e)}}
async function loadJob(){clearResult();previewItems.value=[];previewRefs.value=[];error.value='';try{const r=await api<any>(`/imports/${jobId.value}`);previewItems.value=r.data.items.map((i:any)=>({...i,jobVersion:r.data.row_version}));models.value=previewItems.value[0]?.suggestions?.optical_models??[];previewRefs.value=previewOptions.value.map((p:any)=>p.key);previewDeclarations.value=Object.fromEntries(previewOptions.value.map((p:any)=>[p.key,{sample_id:sampleId.value,stage:'',stage_seq:'',optical_model_id:'',confirmed:false}]))}catch(e){error.value=errorText(e)}}
function displayNumber(value:any){if(value===null||value===undefined)return '—';const n=Number(value);return Number.isFinite(n)?n.toPrecision(8):String(value)}
function sources(){return sourceMode.value==='measurement'?selectedRows.value.map(m=>({kind:'measurement',id:m.measurement_id,expected_row_version:m.row_version})):previewOptions.value.filter((p:any)=>previewRefs.value.includes(p.key)).map((p:any)=>({kind:'import_item',id:p.item.item_id,block_index:p.index,expected_row_version:p.item.jobVersion,...(previewDeclarations.value[p.key]?.confirmed?{confirm_associations:true,sample_id:Number(previewDeclarations.value[p.key]!.sample_id)||null,stage:previewDeclarations.value[p.key]!.stage||null,stage_seq:previewDeclarations.value[p.key]!.stage_seq===''?null:Number(previewDeclarations.value[p.key]!.stage_seq),optical_model_id:Number(previewDeclarations.value[p.key]!.optical_model_id)||null}:{})}))}
async function calculate(){const run=++revision;busy.value=true;result.value=null;saved.value='';error.value='';pairWarning.value='';try{const refs=sources();const keys=pairOptions.value.map((p:any)=>p.key);const paired=before.value!==''||after.value!=='';const body:any={sources:refs,selection:{include_outliers:includeOutliers.value,excluded_points:excluded.value,reason:reason.value}};if(paired){body.before_index=keys.indexOf(before.value);body.after_index=keys.indexOf(after.value);body.confirm_pair=confirmPair.value}let data:any;try{data=(await api<any>('/analysis/calculate',{method:'POST',body})).data}catch(e){if(!paired||!(e instanceof ApiError)||e.status!==422)throw e;pairWarning.value=`差值未计算：${errorText(e)} 以下保留各次原始数据；跨模型不能直接等同于物理刻蚀变化。`;data=(await api<any>('/analysis/calculate',{method:'POST',body:{sources:refs,selection:body.selection}})).data}if(run===revision){result.value=data;stale.value=false}}catch(e){if(run===revision)error.value=errorText(e)}finally{if(run===revision)busy.value=false}}
async function save(){if(!result.value)return;busy.value=true;error.value='';try{const r=await api<any>('/analysis/save',{method:'POST',body:{calculation:result.value.request,label:saveLabel.value}});saved.value=`已保存分析记录 #${r.data.result_id}；原始测点、质量标记和测量记录均未修改。`;await reopenSaved(r.data.result_id)}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function reopenSaved(id:number){try{savedRecord.value=(await api<any>(`/analysis/saved/${id}`)).data}catch(e){error.value=errorText(e)}}
watch([sourceMode,selected,previewRefs],clearResult)
watch([includeOutliers,reason,excluded,before,after,confirmPair,previewDeclarations],()=>{revision++;stale.value=true;saved.value='';busy.value=false},{deep:true})
onMounted(async()=>{await searchSamples();await searchProcesses();try{batches.value=(await api<any[]>('/batches',{query:{size:200}})).data}catch(e){error.value=errorText(e)}if(route.query.job_id){sourceMode.value='import_item';jobId.value=String(route.query.job_id);await loadJob()}else{sampleId.value=String(route.query.sample_id??'');processId.value=String(route.query.process_id??'');if(processId.value&&!processes.value.some(p=>String(p.process_id)===processId.value)){try{const p=(await api<any>(`/processes/${processId.value}`)).data;processes.value.push(p)}catch(e){error.value=errorText(e)}}await loadMeasurements();const mid=Number(route.query.measurement_id);if(mid&&measurements.value.some(m=>m.measurement_id===mid)){selected.value=[mid]}}})
</script>
<template><div class="analysis-view" :class="{'has-analysis-result':result&&!stale}">
<el-alert v-if="pairWarning" :title="pairWarning" type="warning" :closable="false" show-icon/><PageHeading title="科研分析" description="从可信测点查看空间分布、拟合质量与明确选择的前后变化。手动分析无需启用 AI。"/>
<ScientificPlot v-if="result&&!stale" :analysis="result" class="analysis-main-result"/>
<section class="panel panel-body analysis-controls">
<div class="form-grid analysis-filter-grid">
<el-form-item v-if="sourceMode==='measurement'" label="实验执行"><el-select v-model="processId" clearable filterable remote :remote-method="searchProcesses" aria-label="分析执行" placeholder="搜索实验名称 / 执行编号" @change="processChanged"><el-option v-for="p in processes" :key="p.process_id" :label="[p.plan_title,p.process_code].filter(Boolean).join(' · ')" :value="String(p.process_id)"/></el-select></el-form-item>
<el-form-item label="样品"><el-select v-model="sampleId" filterable clearable :remote="!batchId&&!processId" :remote-method="searchSamples" aria-label="分析样品" @change="sampleChanged"><el-option v-for="s in samples" :key="s.sample_id" :label="s.sample_code" :value="String(s.sample_id)"/></el-select></el-form-item>
<el-form-item v-if="sourceMode==='measurement'" label="测量阶段"><el-select v-model="stage" clearable aria-label="分析阶段" @change="loadMeasurements"><el-option v-for="(label,key) in stages" :key="key" :label="label" :value="key"/></el-select></el-form-item>
</div><details class="analysis-source-options"><summary>批次与上传暂存来源</summary><div class="form-grid">
<el-form-item label="数据来源"><el-select v-model="sourceMode" aria-label="分析数据来源"><el-option label="正式测量" value="measurement"/><el-option label="上传暂存预览（未正式入库）" value="import_item"/></el-select></el-form-item>
<el-form-item label="批次"><el-select v-model="batchId" clearable filterable aria-label="分析批次" @change="batchChanged"><el-option v-for="b in batches" :key="b.batch_id" :label="b.batch_code" :value="String(b.batch_id)"/></el-select></el-form-item>
</div></details>
<template v-if="sourceMode==='measurement'"><p class="field-hint">按样品 / 阶段 / 执行筛选当前测量（最多显示 200 条）；勾选最多 20 组。不同样品可并列查看分布，前后差值只允许同一样品、已知阶段与一致模型。</p><el-table :data="measurements" max-height="320" empty-text="没有可见测量。请调整筛选或先上传并确认真实文件。"><el-table-column label="纳入" width="70"><template #default="{row}"><input v-model="selected" type="checkbox" :value="row.measurement_id" :aria-label="`纳入 ${row.measurement_code}`"></template></el-table-column><el-table-column prop="measurement_code" label="测量" min-width="200"/><el-table-column label="阶段"><template #default="{row}">{{ stages[row.stage]??row.stage }} / {{ row.stage_seq??'未知' }}</template></el-table-column><el-table-column prop="point_count" label="测点数"/><el-table-column label="模型"><template #default="{row}">{{ row.optical_model_id?'已关联 · 详情见来源':'模型未知' }}</template></el-table-column></el-table></template>
<template v-else><div class="analysis-inline"><el-input v-model="jobId" aria-label="导入任务编号" placeholder="导入任务编号"/><el-button :disabled="!/^\d+$/.test(jobId)" @click="loadJob">读取我的导入任务</el-button></div><p class="field-hint">仅读取当前用户上传的可信 Eoptics 测量块。RGA / XPS 未验证文件只显示归档状态，不能可信绘图。</p><p v-for="i in previewItems.filter(i=>i.parse_result?.status!=='parsed')" :key="i.item_id">{{ i.filename }}：原件暂存 / 归档，不能可信绘图。</p><label v-for="p in previewOptions" :key="p.key" class="analysis-check"><input v-model="previewRefs" type="checkbox" :value="p.key">{{ p.label }}</label><div v-for="p in previewOptions.filter(p=>previewRefs.includes(p.key))" :key="'declaration-'+p.key" class="preview-declaration"><h3>{{ p.label }}：分析关联</h3><div v-if="previewDeclarations[p.key]" class="form-grid"><el-form-item label="样品"><el-select v-model="previewDeclarations[p.key]!.sample_id" filterable aria-label="预览文件样品"><el-option v-for="s in samples" :key="s.sample_id" :label="s.sample_code" :value="String(s.sample_id)"/></el-select></el-form-item><el-form-item label="阶段"><el-select v-model="previewDeclarations[p.key]!.stage" aria-label="预览文件阶段"><el-option v-for="(label,key) in stages" :key="key" :label="label" :value="key"/></el-select></el-form-item><el-form-item label="阶段序号"><el-input v-model="previewDeclarations[p.key]!.stage_seq" aria-label="预览文件阶段序号"/></el-form-item><el-form-item label="光学模型"><el-select v-model="previewDeclarations[p.key]!.optical_model_id" clearable aria-label="预览文件模型"><el-option v-for="m in models" :key="m.model_id" :label="m.model_name??String(m.model_id)" :value="String(m.model_id)"/></el-select></el-form-item></div><label v-if="previewDeclarations[p.key]" class="analysis-check"><input v-model="previewDeclarations[p.key]!.confirmed" type="checkbox">我已核对本文件的样品、阶段和模型（仅本次分析，不创建正式测量）</label></div><p class="field-hint">逐个文件确认关联后可选择前后比较。未知阶段或不同模型只可并列查看原始分布，服务器拒绝计算差值。</p></template>
<details class="analysis-quality"><summary>异常点纳入与排除理由</summary><label class="analysis-check"><input v-model="includeOutliers" type="checkbox">纳入原有异常标记点（默认保留全部原值）</label>
<el-input v-model="reason" type="textarea" aria-label="分析排除理由" placeholder="排除异常点或指定测点时必须填写理由；记录随结果一起导出。" maxlength="4000"/></details>
<div class="form-grid pair-fields"><el-form-item label="前测（可不选）"><el-select v-model="before" clearable aria-label="分析前测"><el-option v-for="p in pairOptions" :key="p.key" :label="p.label" :value="p.key"/></el-select></el-form-item><el-form-item label="后测（可不选）"><el-select v-model="after" clearable aria-label="分析后测"><el-option v-for="p in pairOptions" :key="p.key" :label="p.label" :value="p.key"/></el-select></el-form-item></div>
<label v-if="before||after" class="analysis-check"><input v-model="confirmPair" type="checkbox">我已核对前后方向与配对依据；差值仍须通过服务器模型可比性校验。Δd = 后测 − 前测</label>
<el-button type="primary" :loading="busy" :disabled="!pairOptions.length||pairOptions.length>20" @click="calculate">按当前选择计算并绘图</el-button>
</section>
<StatePanel v-if="error" tone="error" title="分析未完成" :description="error"/>
<p v-if="result&&stale" role="status" class="danger-text">选择已变化，下方仍是上次计算结果。请点击“按当前选择计算并绘图”后再导出或保存。</p>
<template v-if="result"><section class="panel panel-body"><h2>统计与选择记录</h2><p class="field-hint">当前选择 {{ result.series.length }} 组；所有统计由同一服务器计算函数完成。修改纳入条件需重新计算。MSE 不作厚度误差条。</p><el-table :data="result.series"><el-table-column label="来源" min-width="200"><template #default="{row}">{{ row.source.label }}</template></el-table-column><el-table-column prop="raw_count" label="原始点数"/><el-table-column prop="included_count" label="纳入"/><el-table-column label="均值 (nm)" min-width="200"><template #default="{row}"><span :title="row.statistics.thickness_nm?.mean">{{ displayNumber(row.statistics.thickness_nm?.mean) }}</span></template></el-table-column><el-table-column label="空间 SD (n−1, nm)" min-width="200"><template #default="{row}"><span :title="row.statistics.thickness_nm?.sd_sample">{{ displayNumber(row.statistics.thickness_nm?.sd_sample) }}</span></template></el-table-column></el-table>
<div v-if="result.pair" class="pair-result"><h3>前后变化：后测 − 前测</h3><p>配对 {{ result.pair.paired_point_count }} 点；平均变化 {{ result.pair.mean_delta_nm }} nm（{{ {increase:'增加',decrease:'减少',unchanged:'不变'}[result.pair.observation as 'increase'|'decrease'|'unchanged'] }}）</p><p>未配对：前 {{ result.pair.unmatched_before }}、后 {{ result.pair.unmatched_after }}。{{ result.pair.interpretation }}</p></div>
<details v-for="s in result.series" :key="s.source.id+'-'+s.source.block_index"><summary>{{ s.source.label }}：真实测点、原始标记与来源</summary><p class="field-hint">SHA256 {{ s.source.sha256??'旧记录未关联原件' }} · 版本 {{ s.source.row_version }}</p><el-table :data="s.points" max-height="350"><el-table-column label="下次排除" width="100"><template #default="{row}"><input v-model="excluded" type="checkbox" :value="row.key" :aria-label="`排除 ${row.key}`"></template></el-table-column><el-table-column prop="point_no" label="点号"/><el-table-column prop="x_mm" label="X (mm)"/><el-table-column prop="y_mm" label="Y (mm)"/><el-table-column prop="thickness_nm" label="厚度 (nm)"/><el-table-column prop="mse" label="MSE"/><el-table-column label="原始标记"><template #default="{row}">{{ row.is_outlier?'异常（原值保留）':'—' }}</template></el-table-column></el-table></details>
<div v-if="sourceMode==='measurement'&&auth.canWrite" class="analysis-inline"><el-input v-model="saveLabel" aria-label="保存分析名称" placeholder="分析记录名称" maxlength="100"/><el-button :disabled="!saveLabel.trim()||stale" :loading="busy" @click="save">显式保存分析记录</el-button></div><p v-if="saved" role="status">{{ saved }}</p><section v-if="savedRecord" data-testid="saved-analysis-record"><h3>已保存结果 #{{ savedRecord.result_id }}：{{ savedRecord.record.label }}</h3><p role="status">来源有效性：{{ savedRecord.is_valid?'有效':'已失效' }}</p><p>计算时间：{{ savedRecord.computed_at }}</p><p>结果指纹：{{ savedRecord.record.result_sha256 }}</p><p>选择：{{ savedRecord.record.request.selection.include_outliers?'纳入异常标记点':'排除异常标记点' }}；排除点 {{ savedRecord.record.request.selection.excluded_points.join(', ')||'无' }}；理由：{{ savedRecord.record.request.selection.reason||'无' }}</p><p v-for="s in savedRecord.record.sources" :key="s.id">来源 {{ s.label }} · 测量 #{{ s.id }} · 版本 {{ s.row_version }} · 原件 SHA256 {{ s.sha256??'未关联' }} · 测点指纹 {{ s.points_sha256 }}</p><p v-if="!savedRecord.is_valid" class="danger-text">{{ savedRecord.invalid_reasons.join(', ') }}</p><el-button @click="reopenSaved(savedRecord.result_id)">重新读取此保存结果并检查来源</el-button></section><p class="field-hint">计算和导出不会写入科学记录。保存只记录来源版本、选择理由、统计与结果指纹；支持单组或明确前后配对，多组并列分析请导出。</p></section></template>
</div></template>
<style scoped>.analysis-view{display:flex;flex-direction:column}.analysis-filter-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.analysis-source-options>summary,.analysis-quality>summary{color:#076c78;min-height:40px;padding:8px 0}.analysis-controls{background:#f8fafc;border-radius:12px}.analysis-source-options .form-grid{padding-top:16px}@media(max-width:760px){.analysis-filter-grid{grid-template-columns:minmax(0,1fr)}}.analysis-controls{margin-bottom:18px}.analysis-inline{display:flex;align-items:center;gap:12px;margin:16px 0}.analysis-inline .el-input{max-width:420px}.analysis-check{display:flex;align-items:flex-start;gap:8px;margin:14px 0;font-size:14px}.pair-fields{margin-top:18px}.pair-result{padding:16px 0;border-bottom:1px solid var(--line)}details{margin:18px 0}summary{cursor:pointer;font-weight:600}h2{font-size:20px}@media(max-width:640px){.analysis-inline{flex-wrap:wrap}}</style>
